import asyncio, json
from playwright.async_api import async_playwright
URL='file:///home/claude/shots/app.html'
R=[]
def ok(n,c,x=''): R.append(c); print('PASS' if c else 'FAIL', n, x, flush=True)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); ctx = await b.new_context(viewport={'width':1440,'height':900}, accept_downloads=True); pg = await ctx.new_page(); errs=[]
        pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.goto(URL); await pg.wait_for_selector('#main .page'); await pg.wait_for_timeout(600)
        E=pg.evaluate
        async def go(h): await E(f"location.hash==={json.dumps(h)} ? route() : (location.hash={json.dumps(h)})"); await pg.wait_for_timeout(800)
        async def acc(a): await E(f"switchAccount({json.dumps(a)})"); await pg.wait_for_timeout(700)
        async def chip(fk, val): await pg.click(f'.ff-modal [data-fk="{fk}"] .ff-chip[data-chip="{val}"]')
        async def ticks(fk, n, v='ok'):
            for i in range(n): await pg.click(f'.ff-modal [data-fk="{fk}"] tr[data-row="{i}"] .ff-tick[data-tick="{v}"]')
        cur = lambda: E("(()=>{const k=App.route.name==='proposal'?'proposal':'partnership';const x=(k==='proposal'?D.proposals:D.partnerships).find(y=>y.id===App.route.params.id);const s=wfStateOf(k,x).cur;return s&&s.id})()")
        # — البيانات المرجعية من ملفات المؤسسة —
        deps = await E("L('departments')")
        ok('official department names (from the alignment form)', all(d in deps for d in ['الإدارة العامة للمشاريع','الإدارة العامة للاتصال المؤسسي','الإدارة العامة للمشاركة المجتمعية','الإدارة العامة للموارد البشرية والشؤون الإدارية','الإدارة القانونية','الإدارة المالية']))
        ok('old names renamed across records', await E("!D.partnerships.some(p=>(p.departments||[]).includes('إدارة المشاريع')) && !D.proposals.some(x=>x.department==='إدارة المشاريع')"))
        ok('strategic objectives SO1–SO4 and EO', await E("L('goals').map(goalCode).join(',')") == 'SO1,SO2,SO3,SO4,EO')
        ok('new lists: partnership type, domains, relationship origin, finance', await E("['partnerTypes','domains','originTypes','valueTypes','financeModels','financeStatus'].every(k=>L(k).length)") and 'شريك استراتيجي' in await E("L('partnerTypes')") and 'سياحة' in await E("L('domains')"))
        ok('demo profiles only on demo records', await E("D.partnerships.filter(p=>!p.demo).every(p=>!p.ptype&&!p.evals)") and await E("D.partnerships.filter(p=>p.demo&&p.evals).length") >= 5)
        # — منهجية بناء الشراكات داخل المنظومة —
        await acc('team:وعد')
        pid = await E("D.proposals.find(x=>x.status==='submitted').id")
        await go(f'#/proposals/{pid}')
        await pg.click('[data-wfopen="method"]'); await pg.wait_for_selector('.wf-modal')
        ok('step dialog offers filling the form in the platform', await E("!!document.querySelector('.wf-modal [data-wffill=\"methodology\"]')"))
        await pg.click('[data-wffill="methodology"]'); await pg.wait_for_selector('.ff-modal')
        ok('methodology form: partner prefilled, 5 sector options, 8 items', await E("document.querySelector('#ff_partner').value.length>3 && document.querySelectorAll('[data-fk=sector] .ff-chip:not(.add)').length===5 && document.querySelectorAll('.ff-n').length===8"))
        await pg.click('[data-ffsave="done"]'); await pg.wait_for_timeout(300)
        ok('required items enforced', await E("document.querySelectorAll('.ff.invalid').length") >= 4 and await E("!!document.querySelector('.ff-modal')"))
        for k in ['m1','m2','m4','m6']: await pg.fill(f'#ff_{k}', f'نص البند {k} للاختبار.')
        await pg.click('[data-ffsave="done"]'); await pg.wait_for_timeout(900)
        f = await E(f"D.proposals.find(x=>x.id==='{pid}').forms.methodology")
        ok('form saved complete with its number', f['status']=='done' and f['no'].startswith('MTH-'), f['no'])
        ok('step reopens showing the completed form', await E("!!document.querySelector('.wf-modal .wf-form .chip.ok')"))
        await pg.click('.wf-modal [data-wfdo="done"]'); await pg.wait_for_timeout(800)
        ok('form satisfies the step (no file upload needed)', await cur() == 'eval')
        # — التقييم المبدئي: التصنيف ومن فتح الباب —
        await pg.click('[data-wfopen="eval"]'); await pg.wait_for_selector('.wf-modal'); await pg.click('[data-wffill="initialEval"]'); await pg.wait_for_selector('.ff-modal')
        await chip('domain', 'سياحة'); await chip('ptype', 'شريك استراتيجي'); await chip('origin', 'علاقة شخصية')
        await pg.fill('#ff_originBy', 'عضو مجلس الأمناء')
        await ticks('crit', 7); await chip('rec', 'الجهة مناسبة')
        await pg.click('[data-fk="valueTypes"] .ff-chip[data-chip="مالية"]')
        await pg.fill('#ff_valueSar', '250000')
        await pg.click('[data-ffsave="done"]'); await pg.wait_for_timeout(900)
        pf = await E(f"D.proposals.find(x=>x.id==='{pid}').profile")
        ok('initial evaluation records classification and who opened the door', pf['ptype']=='شريك استراتيجي' and pf['domain']=='سياحة' and pf['origin']=='علاقة شخصية' and pf['originBy']=='عضو مجلس الأمناء', pf)
        await pg.fill('#wfNote', 'مناسبة.'); await pg.click('.wf-modal [data-wfdo="yes"]'); await pg.wait_for_timeout(800)
        ok('proposal accepted after the in-platform evaluation', await E(f"D.proposals.find(x=>x.id==='{pid}').status") == 'accepted')
        await pg.click('[data-act="convert"]'); await pg.wait_for_selector('.modal .map-tbl'); await pg.click('.modal [data-ok]'); await pg.wait_for_timeout(1200)
        ptid = await E("App.route.params.id")
        rec = await E(f"(()=>{{const p=D.partnerships.find(x=>x.id==='{ptid}');return [p.ptype,p.origin,p.originBy,(partnerById(p.partnerId)||{{}}).domain,Object.keys(p.forms||{{}}).sort().join(',')]}})()")
        ok('classification, origin, domain and forms carry over to the partnership', rec == ['شريك استراتيجي','علاقة شخصية','عضو مجلس الأمناء','سياحة','initialEval,methodology'], rec)
        ok('partnership page shows the completed forms in the track', await E("document.querySelectorAll('.wf-sec .wf-doc.form.done').length") == 2)
        await pg.click('.wf-sec .wf-doc.form[data-wfform="methodology"]'); await pg.wait_for_selector('.fdoc-modal')
        ok('completed form opens as the designed document with print and Word', await E("!!document.querySelector('.fdoc-modal .fxdoc .fx-steps') && !!document.querySelector('[data-ffprint]') && !!document.querySelector('[data-ffword]')"))
        async with pg.expect_download() as dl: await pg.click('[data-ffword]')
        d = await dl.value
        ok('Word download (.doc)', d.suggested_filename.endswith('.doc'), d.suggested_filename)
        await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        # الطباعة
        await E(f"printForm('partnership', D.partnerships.find(x=>x.id==='{ptid}'), 'methodology')"); await pg.wait_for_timeout(200)
        ok('print renders the formatted document only', await E("document.documentElement.classList.contains('printing-form') && document.querySelectorAll('#formPrint .fx-step').length===8 && !!document.querySelector('#formPrint .ev-top img')"))
        await E("window.dispatchEvent(new Event('afterprint'))")
        # — المواءمة الاستراتيجية —
        await E(f"(()=>{{const p=D.partnerships.find(x=>x.id==='{ptid}');p.wf.steps.meeting={{status:'done',at:nowISO(),by:'اختبار'}};p.wf.steps.draft={{status:'done',at:nowISO(),by:'اختبار'}};p.wf.steps.depts={{status:'done',at:nowISO(),by:'اختبار'}};p.cooperationAreas='1. الاستشارات البيئية.\\n2. بناء القدرات.';return Repo.save('partnerships',p)}})()")
        await acc('dept:الإدارة العامة للاستراتيجية'); await go(f'#/partnerships/{ptid}')
        await pg.click('[data-wfopen="strategy"]'); await pg.wait_for_selector('.wf-modal'); await pg.click('[data-wffill="alignment"]'); await pg.wait_for_selector('.ff-modal')
        ok('alignment form: owner department, participating departments, goals legend', await E("document.querySelector('[data-fk=owner] .ff-chip.on').dataset.chip") == 'الإدارة العامة للمشاريع' and await E("document.querySelectorAll('.ff-legend div').length") == 5)
        ok('clauses prefilled from cooperation areas', await E("document.querySelectorAll('.ff-cl tbody tr').length") == 2)
        await chip('result', 'متوائمة'); await pg.click('[data-ffsave="done"]'); await pg.wait_for_timeout(300)
        ok('each clause must link to a strategic objective', await E("!!document.querySelector('[data-fk=clauses].invalid')"))
        await pg.click('.ff-cl tr[data-row="0"] [data-goal="SO4"]'); await pg.click('.ff-cl tr[data-row="1"] [data-goal="SO1"]'); await pg.click('.ff-cl tr[data-row="1"] [data-goal="EO"]')
        await pg.click('[data-cladd]'); await pg.fill('.ff-cl tr[data-row="2"] textarea', 'إدارة النفايات والاقتصاد الدائري.'); await pg.click('.ff-cl tr[data-row="2"] [data-goal="SO2"]')
        await pg.click('[data-ffsave="done"]'); await pg.wait_for_timeout(900)
        ok('alignment links clauses to objectives', await E(f"D.partnerships.find(x=>x.id==='{ptid}').goalsLinked.sort().join(',')") == 'EO,SO1,SO2,SO4')
        await pg.click('.wf-modal [data-wfdo="yes"]'); await pg.wait_for_timeout(800)
        ok('strategy approves with the in-platform form', await cur() == 'partner')
        # — الخطاب ومراجعة الخطابات —
        await E(f"(()=>{{const p=D.partnerships.find(x=>x.id==='{ptid}');p.wf.steps.partner={{status:'done',at:nowISO(),by:'اختبار'}};return Repo.save('partnerships',p)}})()")
        await acc('team:وعد'); await go(f'#/partnerships/{ptid}')
        await pg.click('[data-wfopen="legal"]'); await pg.wait_for_selector('.wf-modal'); await pg.click('[data-wffill="letter"]'); await pg.wait_for_selector('.ff-modal')
        body = await E("document.querySelector('#ff_body').value")
        pname = await E(f"partnerName(D.partnerships.find(x=>x.id==='{ptid}'))")
        ok('letter generated from the partnership data', pname in body and 'رؤية المملكة 2030' in body and '..' not in body and '.،' not in body, body[:120])
        ok('letter addressed to the Chairman with the CEO signature', await E("document.querySelector('#ff_to1').value") == 'معالي نائب وزير البيئة والمياه والزراعة' and 'باجري' in await E("document.querySelector('#ff_signName').value"))
        await pg.click('[data-ffsave="done"]'); await pg.wait_for_timeout(900)
        ok('team cannot fill the legal review', not await E("!!document.querySelector('.wf-modal [data-wffill=\"letterReview\"]')"))
        await pg.keyboard.press('Escape')
        await acc('dept:الإدارة القانونية'); await go(f'#/partnerships/{ptid}')
        await pg.click('[data-wfopen="legal"]'); await pg.wait_for_selector('.wf-modal'); await pg.click('[data-wffill="letterReview"]'); await pg.wait_for_selector('.ff-modal')
        ok('letter review: subject pulled from the letter, 7 + 2 review items', pname in await E("document.querySelector('#ff_subject').value") and await E("document.querySelectorAll('[data-fk=r1] tbody tr').length") == 7 and await E("document.querySelectorAll('[data-fk=r2] tbody tr').length") == 2)
        await ticks('r1', 7); await chip('r1rec', 'استكمال المراجعة'); await pg.fill('#ff_r2by', 'لجين'); await ticks('r2', 2); await chip('r2rec', 'مناسب بعد التعديلات'); await pg.fill('#ff_apBy', 'لجين')
        await pg.click('[data-ffsave="done"]'); await pg.wait_for_timeout(900)
        ok('letter review numbered GPD-', (await E(f"D.partnerships.find(x=>x.id==='{ptid}').forms.letterReview.no")).startswith('GPD-'))
        await pg.click('.wf-modal [data-wfdo="yes"]'); await pg.wait_for_timeout(800)
        ok('legal approves with both documents completed in the platform', await cur() == 'excellency')
        # — تقييم الشراكة —
        await acc('team:وعد'); await go(f'#/partnerships/{ptid}')
        ok('profile section on the partnership page', await E("!!document.querySelector('#profile') && document.querySelectorAll('#profile .pf-card').length") >= 3)
        await pg.click('[data-evnew]'); await pg.wait_for_selector('.ff-modal')
        for k in ['align','outputs','impact','commit','value','sustain']: await pg.click(f'[data-fk="scores"] tr[data-row="{k}"] .ff-st[data-score="4"]')
        ok('weighted score shown live (all 4 → 80%)', '80%' in await E("document.querySelector('#ffTotal').textContent"))
        await chip('impactLevel', 'مرتفع'); await chip('rec', 'الاستمرار')
        await pg.click('[data-ffsave="done"]'); await pg.wait_for_timeout(900)
        ok('evaluation saved with score and grade', await E(f"lastEval(D.partnerships.find(x=>x.id==='{ptid}')).score") == 80 and 'جيد' in await E("document.querySelector('#profile .pf-ev b').textContent"))
        # — التصنيف والوضع المالي —
        await pg.click('[data-pfedit]'); await pg.wait_for_selector('.ff-modal')
        await chip('model', 'تمويل مشترك'); await pg.fill('#ff_partnerSar', '400000'); await pg.fill('#ff_murojSar', '100000'); await pg.fill('#ff_spentSar', '125000'); await chip('status', 'ضمن الخطة')
        await pg.click('.ff-modal [data-ok]'); await pg.wait_for_timeout(900)
        fin = await E(f"D.partnerships.find(x=>x.id==='{ptid}').finance")
        ok('financial status saved', fin['model']=='تمويل مشترك' and fin['partnerSar']==400000 and fin['spentSar']==125000, fin)
        ok('spend ratio shown', await E("document.querySelector('#profile .pf-spend i').style.width") == '25%')
        # — لوحة المجلس —
        await E("applyDesign('board')"); await pg.wait_for_timeout(900); await go('#/dashboard?v=alt')
        ok('dashboard chapter: evaluation, classification and finance', await E("!!document.querySelector('[data-ch=eval] .bo-ev-score') && !!document.querySelector('[data-ch=eval] .bo-fin')"))
        avg = await E("(()=>{const e=D.partnerships.filter(p=>!p.isDraft&&p.stage==='signed'&&(showDemo()||!p.demo)).map(lastEval).filter(x=>x&&x.score!==null);return Math.round(e.reduce((t,x)=>t+x.score,0)/e.length)})()")
        ok('average evaluation matches records', await E("+document.querySelector('[data-ch=eval] .bo-gauge-t b').dataset.v") == avg, avg)
        tot = await E("D.partnerships.filter(p=>!p.isDraft&&(showDemo()||!p.demo)).reduce((t,p)=>t+(+(p.finance||{}).partnerSar||0)+(+(p.finance||{}).murojSar||0)+(+(p.finance||{}).inkindSar||0),0)")
        ok('portfolio value matches records', await E("+document.querySelector('.bo-fin .tot b').dataset.v") == tot, tot)
        await pg.click('[data-ch=eval] .bo-split-l [data-cf="ptype|شريك استراتيجي"]'); await pg.wait_for_timeout(700)
        ok('clicking a classification filters the briefing', await E("(App.dashF.ptype||[]).join()") == 'شريك استراتيجي')
        await pg.click('[data-reset]'); await pg.wait_for_timeout(500)
        # — الفلاتر في السجل —
        await go('#/partnerships?ptype=شريك خدمات')
        ok('register filters by partnership type', await E("App.lastRegList.length>0 && App.lastRegList.every(p=>p.ptype==='شريك خدمات')"))
        await go('#/partnerships?domain=زراعة')
        ok('register filters by partner domain', await E("App.lastRegList.length>0 && App.lastRegList.every(p=>(partnerById(p.partnerId)||{}).domain==='زراعة')"))
        # — الإعدادات —
        await acc('admin'); await go('#/settings/lists')
        ok('new lists manageable in settings', await E("['partnerTypes','domains','originTypes','financeModels'].every(k=>!!document.querySelector('#list-'+k))"))
        await go('#/settings/roles')
        ok('letter defaults editable in settings', await E("document.querySelectorAll('[data-letter]').length") == 4)
        ok('no page errors', not errs, errs[:3])
        await b.close()
    print(f'\n{sum(R)}/{len(R)} passed')
asyncio.run(main())
